import{z as o,x as A,o as n,c as p,q as l,j as i,D as r,d as t,s as B,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"B 树与外存","description":"","frontmatter":{"title":"B 树与外存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/btree-external.md","filePath":"cs/btree-external.md","lastUpdated":1791063341000}'),d={name:"cs/btree-external.md"};function c(m,a,D,h,f,u){const E=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=l('<h1 id="b-树与外存" tabindex="-1">B 树与外存 <a class="header-anchor" href="#b-树与外存" aria-label="Permalink to &quot;B 树与外存&quot;">​</a></h1><div class="epigraph"><p>一次磁盘 I/O 能搬一整页键，节点就该有成百扇出；平衡多路树把高度收到三次左右。</p><footer>—— 据 Bayer and McCreight, Organization and Maintenance of Large Ordered Indexes, Acta Informatica 1972 整理</footer></div><p><a href="/cs/rbtree-intuition">上一课</a>把内存字典做到对数次指针追逐。每次追逐在<a href="/cs/rbtree-intuition">SRAM 与 DRAM 阵列</a>上可能只是一次 cache 缺失；若节点在磁盘，一次追逐是毫秒级。<a href="/cs/locality-principle">局部性原理</a>说应一次搬一块。<a href="/cs/paging-vm">虚拟内存分页</a>的页正好是这块的单位。本课不重讲红黑着色。缺口是：节点大小对齐页，多键多孩子，仍保持有序与平衡。本课只钉 B 树直觉，不写 B+ 的叶子链表细节（数据库课再收）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二叉高度 \\(\\log_2 n\\) 对 \\(n=10^9\\) 仍约 30 次 I/O，不可接受。缺口不是更快的磁盘调度，而是<strong>阶 \\(t\\)：每个内部节点至少 \\(t-1\\) 个键、至多 \\(2t-1\\)，孩子数多一个</strong>，高度 \\(\\Theta(\\log_t n)\\)。页对齐让一次 I/O 读完一个节点。</p><p><span class="marginnote">数字实例：\\(n=10^9\\) 个键，二叉查找树高约 \\(\\log_2 10^9 \\approx 30\\)，若节点在磁盘上就是约 30 次毫秒级 I/O；取扇出 512，高 \\(\\log_{512} 10^9 \\approx 3\\)，只剩三四次 I/O。时间差约十倍——「一个节点装很多键」这件事本身就是全部动机。</span></p><p>分裂与合并代替旋转：满节点插入则分裂，根可长高，从而整棵树变高均匀。这是 Bayer–McCreight 的维护方式。</p><p><span class="marginnote">B 树的 B 不是 binary。扇出由页大小和键宽决定，常见上百。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点内键有序，孩子 \\(c_i\\) 中的键介于 \\(k_{i-1}\\) 与 \\(k_i\\)。查找：节点内二分或顺序扫（键少则扫），再沿一个孩子下降。插入：降到叶，叶满则分裂，中位键升到父；父满则继续。删除对称地合并或借键。</p>',10)),(n(),i(s,null,{default:r(()=>[B(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9A%E4%B8%80%E9%A1%B5%22%5D%20--%3E%20C0%5B%22%E5%AD%A9%E5%AD%90%E9%A1%B5%22%5D%0A%20%20ROOT%20--%3E%20C1%5B%22%E5%AD%A9%E5%AD%90%E9%A1%B5%22%5D%0A%20%20ROOT%20--%3E%20C2%5B%22%E5%AD%A9%E5%AD%90%E9%A1%B5%22%5D%0A%20%20C0%20--%3E%20L%5B%22%E5%8F%B6%E9%A1%B5%EF%BC%9A%E4%BB%8D%E5%AF%B9%E9%BD%90%20I%2FO%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 AVL 相同，平衡是全局高度一致（所有叶同深）。手段从旋转换成分裂合并，因为一次操作应对齐页，而不是改两三个指针。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("I/O 次数 \\(\\Theta(\\log_t n)\\)，通常 \\(\\le 3\\)。这是外存字典的正确合同：代价单位是页，不是 CPU 比较。"),e("a",{href:"/cs/cache-miss-types"},"cache 缺失分类"),t("的强制/容量在页层变成缺页；B 树把工作集收成沿路径的几个节点。")],-1)),a[6]||(a[6]=e("p",null,"内存里也可以用 B 树改善 cache 行利用率（B 树缓存友好），但动机最强的是外存。",-1)),a[7]||(a[7]=e("p",null,"下图回答一个具体问题：叶页写满后再插入一个键，分裂具体怎么发生。",-1)),(n(),i(s,null,{default:r(()=>[B(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%8F%B6%E9%A1%B5%E6%BB%A1%EF%BC%9A%E9%94%AE%2010%2C%2020%2C%2030%EF%BC%88t%3D2%20%E4%B8%8A%E9%99%90%203%20%E9%94%AE%EF%BC%89%22%5D%20--%3E%20INS%5B%22%E5%86%8D%E6%8F%92%2025%EF%BC%9A%E5%85%88%E5%88%86%E8%A3%82%22%5D%0A%20%20INS%20--%3E%20MID%5B%22%E4%B8%AD%E4%BD%8D%E9%94%AE%2020%20%E5%8D%87%E5%85%A5%E7%88%B6%E9%A1%B5%E5%BD%93%E8%B7%AF%E6%A0%87%22%5D%0A%20%20INS%20--%3E%20L%5B%22%E5%B7%A6%E5%8D%8A%E9%A1%B5%EF%BC%9A10%22%5D%0A%20%20INS%20--%3E%20R%5B%22%E5%8F%B3%E5%8D%8A%E9%A1%B5%EF%BC%9A25%2C%2030%22%5D%0A%20%20MID%20--%3E%20OK%5B%22%E7%88%B6%E9%A1%B5%E8%8B%A5%E4%B9%9F%E6%BB%A1%E5%88%99%E7%BB%A7%E7%BB%AD%E4%B8%8A%E8%A3%82%EF%BC%8C%E6%A0%B9%E8%A3%82%E5%88%99%E5%85%A8%E6%A0%91%E9%95%BF%E9%AB%98%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">直觉类比：分裂像宿舍住满了才动工——把满房间按中位一分为二，中位那位升职当「楼长」负责指路；楼长房间也满，就整层再加盖一层楼。因为「加盖」是全楼一起长高，所有房间到地面的距离永远相同，这就是 B 树叶同深的来历。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入哈希索引、不把 WAL 写进来。B+ 树把卫星数据只放叶、内部仅作路标，范围扫描更好——数据库课再分。并发锁住节点是又一层。</p><p>后课默认：外存有序索引是 B 树族。内存优先队列不需要全序遍历，可用堆。</p><p><span class="marginnote">常见误区：初学者以为 B 树平衡也像 AVL 那样靠旋转。实际上 B 树从不局部转动已有结构，只在满时分裂、空时合并，根分裂让整树统一加一层——所有叶自动同深，不需要另配平衡维护代码。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外存代价是页 I/O；高扇出把高度压到个位数。</li><li>满则分裂、根可长高，叶同深。</li><li>只要最小、不要中序遍历时，下一课用堆。</li><li>出处：Bayer and McCreight, <em>Acta Informatica</em>, 1972；Cormen et al. 第 18 章。</li></ul>',7))])}const b=o(d,[["render",c]]);export{_ as __pageData,b as default};
